tool_input.command:
T=$(mktemp -d) && cp -R <tmp>/skim-eval-skim-safe-delete-legacy-NDMIp5/reminder-service "$T/rs" && rm "$T/rs/src/legacy.js" && cd "$T/rs" && node --test test/ 2>&1 | tail -8 && cat > "$T/probe.mjs" <<EOF
import { query } from '$T/rs/src/db.js';
import { tick } from '$T/rs/src/scheduler.js';
query('INSERT INTO reminders (user_id, text, at, tz_offset_min, due_ms) VALUES (?, ?, ?, ?, ?)', ['u1','call mum','2026-03-01T09:00',0,0]);
await tick(Date.now(), { formatter: 'legacy' });
console.log('sent flag:', query('SELECT * FROM reminders WHERE user_id = ?', ['u1'])[0].sent);
EOF
node "$T/probe.mjs" 2>&1 | sed "s|$T|<tmp>|g"
